class Box<T> {
    private T value;

    void set(T v) { this.value = v; }
    T get() { return this.value; }
}

Box<String> spellBox = new Box<>();
spellBox.set("Fireball");
String name = spellBox.get(); // no cast needed

Box<Integer> manaBox = new Box<>();
