class Pair<K, V> {
    private K key;
    private V value;

    Pair(K key, V value) {
        this.key = key;
        this.value = value;
    }

    K getKey()   { return key; }
    V getValue() { return value; }

    @Override
    public String toString() {
        return "(" + key + ", " + value + ")";
    }
}

Pair<String, Integer> score = new Pair<>("Eldrin", 9000);
System.out.println(score); // (Eldrin, 9000)

