// T must implement Comparable<T>
public static <T extends Comparable<T>> T max(T a, T b) {
    return a.compareTo(b) >= 0 ? a : b;
}

// Works for any Comparable type
System.out.println(max(10, 25));        // 25
System.out.println(max("apple", "mango")); // mango
System.out.println(max(3.14, 2.71));    // 3.14

class Sorter {
    // Generic method — <T> before return type is required
    public static <T extends Comparable<T>> void bubbleSort(T[] arr) {
        int n = arr.length;
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < n - i - 1; j++) {
                if (arr[j].compareTo(arr[j + 1]) > 0) {
                    T temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                }
            }
        }
    }
}

Integer[] scores = {42, 7, 99, 13};
Sorter.bubbleSort(scores);
System.out.println(Arrays.toString(scores)); // [7, 13, 42, 99]

